use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

/// 9999-12-31T23:59:59Z. Clamping here keeps the date at four year digits,
/// so `len(date) == 10` holds for any clock reading.
const MAX_SECONDS: u64 = 253_402_300_799;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len() * 3);
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

/// Converts days since 1970-01-01 to a proleptic Gregorian (year, month, day).
/// Uses Howard Hinnant's civil_from_days algorithm on non-negative day counts.
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

fn format_date(seconds: u64) -> String {
    let secs = seconds.min(MAX_SECONDS);
    let (y, m, d) = civil_from_days(secs / 86_400);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Enrichment lookup requested by the graph's author. The result is
        // deliberately not used: the node's output must not change. A transport
        // failure comes back as a value and is ignored.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&tick.reason));
        let _ = http_client::fetch(&url);

        let now = wall_clock::now();
        RunInfo {
            date: format_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
```

Note: the component now imports `aap:caps/http-client@0.1.0`, which the current graph definition's `with Clock` does not grant. A validator or host that checks imports against the declared grant will refuse this component until you ship the graph update that adds the capability. The handle's allowlist also has to include `metadata.internal.example`. If it doesn't, the host traps at the call, and `fetch` does not return that as an error value.

